using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using BiliIndexTranslate.Core.Translation;

namespace BiliIndexTranslate.Core.Study;

/// <summary>
/// Tolerant full &amp; streaming parser for structured Study Card JSON generated by OpenAI-compatible
/// models (including 9B models that occasionally emit unquoted /IPA/, curly quotes, outside-quote
/// parenthesized glosses, or mixed delimiters).
/// </summary>
public static partial class StudyCardParser
{
    [GeneratedRegex(@"(:\s*)/([^/\r\n]+)/(\s*[,}\]])")]
    private static partial Regex UnquotedSlashRegex();

    [GeneratedRegex(@"""([^""\r\n]+)""\s*([（(][^)）\r\n]+[）)])(\s*[,\]}])")]
    private static partial Regex OutsideParenGlossRegex();

    [GeneratedRegex(@",(\s*[}\]])")]
    private static partial Regex TrailingCommaRegex();

    [GeneratedRegex(@"^[""\u201c'][A-Za-z0-9_]+[""\u201d']\s*:")]
    private static partial Regex NextObjectKeyRegex();

    [GeneratedRegex(@"^[a-zA-Z]{2,3}(-[A-Za-z0-9]{2,8})*$")]
    private static partial Regex Bcp47Regex();

    [GeneratedRegex(@"""sourceLang""\s*:\s*""([A-Za-z]{2,3}(?:-[A-Za-z0-9]{2,8})*)""")]
    private static partial Regex PartialLangRegex();

    [GeneratedRegex(@"""mode""\s*:\s*""(word|sentence)""")]
    private static partial Regex PartialModeRegex();

    [GeneratedRegex(@"""grammarNote""\s*:\s*""((?:\\.|[^""\\])*)""")]
    private static partial Regex PartialGrammarRegex();

    public static bool TryParseCompletion(string? completionBody, string sourceText, out StudyDeck? deck, out string? error)
    {
        deck = null;
        if (!ChatCompletionParser.TryParse(completionBody, out var content, out error))
            return false;

        deck = ParseContent(content, sourceText);
        if (deck is null)
        {
            error = "The service returned an empty study card.";
            return false;
        }
        return true;
    }

    public static StudyDeck? ParseContent(string? rawContent, string sourceText)
    {
        var text = (rawContent ?? string.Empty).Trim();
        if (text.Length == 0) return null;

        var stripped = StripCodeFence(text);
        if (TryParseJsonDeck(stripped, sourceText, out var directDeck))
            return directDeck;

        var repaired = RepairJson(text);
        if (TryParseJsonDeck(repaired, sourceText, out var repairedDeck))
            return repairedDeck;

        var recovered = ExtractPartialDeck(text, sourceText);
        if (recovered is { Cards.Count: > 0 })
            return recovered with { IsStreaming = false };

        var head = (sourceText ?? string.Empty).Trim();
        var wordCount = head.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries).Length;
        var term = head.Length > 48 ? head[..48] + "…" : (head.Length > 0 ? head : "Selection");
        return new StudyDeck(
            wordCount > 4 ? StudyCardMode.Sentence : StudyCardMode.Word,
            InferSourceLanguage(head),
            string.Empty,
            new[]
            {
                new StudyCardItem(term, string.Empty, string.Empty, string.Empty, string.Empty, text, string.Empty, string.Empty, Array.Empty<string>(), null),
            });
    }

    /// <summary>
    /// Extracts completed <c>grammarNote</c> and completed <c>cards[i]</c> items from an in-flight
    /// SSE JSON buffer so Card 1 renders immediately while subsequent cards are still streaming.
    /// </summary>
    public static StudyDeck? ExtractPartialDeck(string? partialRaw, string sourceText)
    {
        var s = partialRaw ?? string.Empty;
        if (s.Length == 0) return null;

        var fallbackLang = InferSourceLanguage(sourceText);
        var langMatch = PartialLangRegex().Match(s);
        var sourceLang = langMatch.Success ? langMatch.Groups[1].Value : fallbackLang;

        var modeMatch = PartialModeRegex().Match(s);
        var grammarMatch = PartialGrammarRegex().Match(s);
        var grammarNote = grammarMatch.Success
            ? grammarMatch.Groups[1].Value.Replace("\\n", "\n").Replace("\\\"", "\"").Trim()
            : string.Empty;

        var cards = new List<StudyCardItem>();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var cardsIdx = s.IndexOf("\"cards\"", StringComparison.Ordinal);
        if (cardsIdx >= 0)
        {
            var arrStart = s.IndexOf('[', cardsIdx);
            if (arrStart >= 0)
            {
                var depth = 0;
                var inStr = false;
                var objStart = -1;
                for (var i = arrStart + 1; i < s.Length; i++)
                {
                    var ch = s[i];
                    if (inStr)
                    {
                        if (ch == '\\') i++;
                        else if (ch == '"') inStr = false;
                        continue;
                    }
                    if (ch == '"') { inStr = true; continue; }
                    if (ch == '{')
                    {
                        if (depth == 0) objStart = i;
                        depth++;
                    }
                    else if (ch == '}')
                    {
                        depth--;
                        if (depth == 0 && objStart >= 0)
                        {
                            var rawCard = s[objStart..(i + 1)];
                            objStart = -1;
                            try
                            {
                                using var doc = JsonDocument.Parse(RepairJson(rawCard));
                                if (TryReadCard(doc.RootElement, sourceText, out var item) && item is not null && seen.Add(item.Term))
                                {
                                    cards.Add(item);
                                    if (cards.Count >= 4) break;
                                }
                            }
                            catch (JsonException)
                            {
                                // Ignore malformed partial object until final parse.
                            }
                        }
                    }
                    else if (ch == ']' && depth == 0)
                    {
                        break;
                    }
                }
            }
        }

        if (grammarNote.Length == 0 && cards.Count == 0) return null;

        var mode = (modeMatch.Success && modeMatch.Groups[1].Value == "sentence") || cards.Count > 1 || grammarNote.Length > 0
            ? StudyCardMode.Sentence
            : StudyCardMode.Word;

        return new StudyDeck(mode, sourceLang, grammarNote, cards, IsStreaming: true);
    }

    public static string InferSourceLanguage(string? text)
    {
        if (string.IsNullOrEmpty(text)) return "en-US";
        foreach (var ch in text)
        {
            if (ch is >= '\u3040' and <= '\u30FF') return "ja-JP";
            if ((ch >= '\uAC00' && ch <= '\uD7AF') || (ch >= '\u1100' && ch <= '\u11FF')) return "ko-KR";
            if (ch is >= '\u0400' and <= '\u04FF') return "ru-RU";
        }
        foreach (var ch in text)
        {
            if (ch is >= '\u4E00' and <= '\u9FFF') return "zh-CN";
        }
        return "en-US";
    }

    public static string RepairJson(string raw)
    {
        var s = StripCodeFence((raw ?? string.Empty).Trim());
        var start = s.IndexOf('{');
        var end = s.LastIndexOf('}');
        if (start >= 0 && end > start)
            s = s[start..(end + 1)];

        s = UnquotedSlashRegex().Replace(s, m =>
        {
            var pre = m.Groups[1].Value;
            var ipa = m.Groups[2].Value.Replace("\\", "\\\\").Replace("\"", "\\\"");
            var post = m.Groups[3].Value;
            return $"{pre}\"/{ipa}/\"{post}";
        });

        s = OutsideParenGlossRegex().Replace(s, "\"$1 $2\"$3");

        var stack = new List<char>(8);
        var sb = new StringBuilder(s.Length + 32);
        var inString = false;
        var isKeyString = false;
        var expectingKey = false;

        for (var i = 0; i < s.Length; i++)
        {
            var ch = s[i];

            if (!inString)
            {
                if (char.IsWhiteSpace(ch)) { sb.Append(ch); continue; }
                if (ch == '{') { stack.Add('{'); expectingKey = true; sb.Append(ch); continue; }
                if (ch == '[') { stack.Add('['); expectingKey = false; sb.Append(ch); continue; }
                if (ch is '}' or ']')
                {
                    if (stack.Count > 0) stack.RemoveAt(stack.Count - 1);
                    expectingKey = false;
                    sb.Append(ch);
                    continue;
                }
                if (ch == ':') { expectingKey = false; sb.Append(ch); continue; }
                if (ch == ',')
                {
                    expectingKey = stack.Count > 0 && stack[^1] == '{';
                    sb.Append(ch);
                    continue;
                }
                if (ch is '"' or '\u201c' or '\'')
                {
                    inString = true;
                    isKeyString = expectingKey;
                    expectingKey = false;
                    sb.Append('"');
                    if (ch == '\u201c' && !isKeyString)
                        sb.Append('\u201c');
                    continue;
                }
                expectingKey = false;
                sb.Append(ch);
                continue;
            }

            if (ch == '\\')
            {
                if (i + 1 < s.Length)
                {
                    var next = s[++i];
                    if ("\"\\/bfnrtu".Contains(next)) sb.Append('\\').Append(next);
                    else sb.Append(next);
                }
                else sb.Append("\\\\");
                continue;
            }

            if (ch == '\r') continue;
            if (ch == '\n') { sb.Append("\\n"); continue; }
            if (ch == '\t') { sb.Append("\\t"); continue; }

            if (ch is '"' or '\u201d' or '\'')
            {
                var k = i + 1;
                while (k < s.Length && char.IsWhiteSpace(s[k])) k++;
                var next = k < s.Length ? s[k] : '\0';

                var closes = false;
                if (isKeyString)
                {
                    closes = next == ':';
                }
                else
                {
                    var top = stack.Count > 0 ? stack[^1] : '{';
                    if (next is '}' or ']' or '\0') closes = true;
                    else if (next == ',')
                        closes = top == '[' ? IsLikelyArrayBoundary(s, k + 1) : IsLikelyObjectBoundary(s, k + 1);
                }

                if (closes) { sb.Append('"'); inString = false; }
                else if (ch == '"') sb.Append("\\\"");
                else sb.Append(ch);
                continue;
            }

            sb.Append(ch);
        }

        if (inString) sb.Append('"');
        return TrailingCommaRegex().Replace(sb.ToString(), "$1");
    }

    private static bool IsLikelyObjectBoundary(string s, int afterCommaIdx)
    {
        var k = afterCommaIdx;
        while (k < s.Length && char.IsWhiteSpace(s[k])) k++;
        if (k >= s.Length || s[k] == '}') return true;
        var len = Math.Min(48, s.Length - k);
        return NextObjectKeyRegex().IsMatch(s.AsSpan(k, len));
    }

    private static bool IsLikelyArrayBoundary(string s, int afterCommaIdx)
    {
        var k = afterCommaIdx;
        while (k < s.Length && char.IsWhiteSpace(s[k])) k++;
        if (k >= s.Length || s[k] == ']') return true;
        return s[k] is '"' or '\u201c' or '\'' or '{';
    }

    private static string StripCodeFence(string text)
    {
        var s = text.Trim();
        if (s.StartsWith("```", StringComparison.Ordinal))
        {
            var firstNl = s.IndexOf('\n');
            if (firstNl >= 0) s = s[(firstNl + 1)..];
            if (s.EndsWith("```", StringComparison.Ordinal)) s = s[..^3];
        }
        return s.Trim();
    }

    private static bool TryParseJsonDeck(string json, string sourceText, out StudyDeck? deck)
    {
        deck = null;
        JsonDocument doc;
        try { doc = JsonDocument.Parse(json); }
        catch (JsonException) { return false; }

        using (doc)
        {
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object) return false;

            var fallbackLang = InferSourceLanguage(sourceText);
            var rawLang = ReadStr(root, "sourceLang", "lang", "language");
            var sourceLang = Bcp47Regex().IsMatch(rawLang) ? rawLang : fallbackLang;
            var grammarNote = ReadStr(root, "grammarNote", "grammar", "structure");

            var items = new List<StudyCardItem>();
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (root.TryGetProperty("cards", out var cardsEl) && cardsEl.ValueKind == JsonValueKind.Array)
            {
                foreach (var c in cardsEl.EnumerateArray())
                {
                    if (TryReadCard(c, sourceText, out var item) && item is not null && seen.Add(item.Term))
                    {
                        items.Add(item);
                        if (items.Count >= 4) break;
                    }
                }
            }
            else if (TryReadCard(root, sourceText, out var single))
            {
                items.Add(single!);
            }

            if (items.Count == 0) return false;

            if (items[0].Example is null && root.TryGetProperty("example", out var rootEx) && rootEx.ValueKind == JsonValueKind.Object)
            {
                var exSrc = ReadStr(rootEx, "source", "sentence");
                var exTgt = ReadStr(rootEx, "target", "translation");
                if (exSrc.Length > 0 || exTgt.Length > 0)
                    items[0] = items[0] with { Example = new StudyExample(exSrc, exTgt) };
            }

            var rawMode = ReadStr(root, "mode");
            var mode = rawMode.Equals("sentence", StringComparison.OrdinalIgnoreCase)
                       || items.Count > 1
                       || grammarNote.Length > 0
                ? StudyCardMode.Sentence
                : StudyCardMode.Word;

            deck = new StudyDeck(mode, sourceLang, grammarNote, items, IsStreaming: false);
            return true;
        }
    }

    private static bool TryReadCard(JsonElement el, string sourceText, out StudyCardItem? item)
    {
        item = null;
        if (el.ValueKind != JsonValueKind.Object) return false;

        var term = ReadStr(el, "term", "word", "headword");
        var meaning = ReadStr(el, "meaning", "definition", "translation");
        if (term.Length == 0 && meaning.Length == 0) return false;

        if (term.Length == 0)
        {
            var fallback = (sourceText ?? string.Empty).Trim();
            term = fallback.Length > 60 ? fallback[..60] : fallback;
        }

        var surface = ReadStr(el, "surface");
        if (surface.Equals(term, StringComparison.OrdinalIgnoreCase))
            surface = string.Empty;

        var reading = ReadStr(el, "reading", "phonetic", "ipa", "pronunciation");
        var pos = ReadStr(el, "pos", "partOfSpeech");
        var register = ReadStr(el, "register", "tone", "style");
        var nuance = ReadStr(el, "nuance", "synonyms", "usage");
        var memoryAid = ReadStr(el, "memoryAid", "etymology", "mnemonic");

        var collocations = new List<string>();
        if (el.TryGetProperty("collocations", out var colEl))
        {
            if (colEl.ValueKind == JsonValueKind.Array)
            {
                foreach (var entry in colEl.EnumerateArray())
                {
                    if (entry.ValueKind == JsonValueKind.String)
                    {
                        var v = (entry.GetString() ?? string.Empty).Trim();
                        if (v.Length > 0 && collocations.Count < 5) collocations.Add(v);
                    }
                }
            }
            else if (colEl.ValueKind == JsonValueKind.String)
            {
                var v = (colEl.GetString() ?? string.Empty).Trim();
                if (v.Length > 0) collocations.Add(v);
            }
        }

        StudyExample? example = null;
        if (el.TryGetProperty("example", out var exEl))
        {
            if (exEl.ValueKind == JsonValueKind.Object)
            {
                var exSrc = ReadStr(exEl, "source", "sentence", "original");
                var exTgt = ReadStr(exEl, "target", "translation", "meaning");
                if (exSrc.Length > 0 || exTgt.Length > 0)
                    example = new StudyExample(exSrc, exTgt);
            }
            else if (exEl.ValueKind == JsonValueKind.String)
            {
                var exSrc = (exEl.GetString() ?? string.Empty).Trim();
                if (exSrc.Length > 0) example = new StudyExample(exSrc, string.Empty);
            }
        }

        item = new StudyCardItem(term, surface, reading, pos, register, meaning, nuance, memoryAid, collocations, example);
        return true;
    }

    private static string ReadStr(JsonElement obj, params string[] names)
    {
        foreach (var name in names)
        {
            if (obj.TryGetProperty(name, out var prop))
            {
                if (prop.ValueKind == JsonValueKind.String)
                    return (prop.GetString() ?? string.Empty).Trim();
                if (prop.ValueKind is JsonValueKind.Number or JsonValueKind.True or JsonValueKind.False)
                    return prop.ToString().Trim();
            }
        }
        return string.Empty;
    }
}
